import os,sys
def real(p,rev):
    if p.startswith('/app/config/'):
        rel=p[len('/app/config/'):]
        for r in range(rev+1,430):
            q=f'/app/config-history/r{r:04d}/prev/{rel}'
            if os.path.exists(q): return q
    return p
def resolve(svc,env,host,rev):
    vals={}
    def proc(p):
        sec=None
        for l in open(real(p,rev)):
            l=l.strip()
            if not l or l.startswith('#'): continue
            if l.startswith('['): sec=l[1:-1].strip(); continue
            k,_,v=[x.strip() for x in l.partition('=')]
            if k=='include':
                if sec is None:
                    proc(os.path.normpath(os.path.join(os.path.dirname(p),v.replace('${env}',env).replace('${host}',host))))
                continue
            if sec is None or sec==vals.get('name'): vals[k]=v
    proc(f'/app/services/{svc}/service.conf')
    return vals
if __name__=='__main__':
    print(resolve(sys.argv[1],sys.argv[2],sys.argv[3],int(sys.argv[4])))
